tape( 'the function supports view offsets', function test( t ) {
	var expected;
	var mask0;
	var mask1;
	var x0;
	var x1;

	x0 = new Complex64Array([
		1.0,
		2.0,
		3.0,   // 0
		4.0,   // 0
		5.0,
		6.0,
		7.0,   // 1
		8.0,   // 1
		9.0,
		10.0,
		11.0, // 2
		12.0  // 2
	]);
	mask0 = new Uint8Array([
		0,
		0, // 0
		0, // 1
		0  // 2
	]);
	expected = new Complex64Array([
		1.0,
		2.0,
		11.0, // 0
		12.0, // 0
		5.0,
		6.0,
		7.0,   // 1
		8.0,   // 1
		9.0,
		10.0,
		3.0,   // 2
		4.0    // 2
	]);

	x1 = new Complex64Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );
	mask1 = new Uint8Array( mask0.buffer, mask0.BYTES_PER_ELEMENT*1 );

	cmskrev( 3, x1, 2, mask1, 1 );
	t.strictEqual( isSameComplex64Array( x0, expected ), true, 'returns expected value' );
	t.end();
});
